package com.kideyeguard

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.time.LocalTime

class CoreLogicTest {

    @Test
    fun activationCodeVerificationMatchesPythonKeygen() {
        // Real code generated by kid-eye-guard-win/keygen.py
        assertTrue(LicenseManager.verifyActivationCode("KEG-DPJE-JVHS-1242"))
        assertTrue(LicenseManager.verifyActivationCode("keg-dpje-jvhs-1242"))
        assertFalse(LicenseManager.verifyActivationCode("KEG-DPJE-JVHS-1243"))
        assertFalse(LicenseManager.verifyActivationCode("INVALID-CODE"))
    }

    @Test
    fun mathChallengeGeneratesValidProblems() {
        for (level in listOf("easy", "medium", "hard")) {
            val probs = MathChallenge.generate(level, 3)
            assertEquals(3, probs.size)
            for (p in probs) {
                assertTrue(p.prompt.contains("= ?"))
            }
        }
    }

    @Test
    fun curfewOvernightAndDaytimeLogic() {
        assertTrue(GuardPrefs.isInCurfew(LocalTime.of(22, 15), "21:30", "07:00"))
        assertTrue(GuardPrefs.isInCurfew(LocalTime.of(6, 30), "21:30", "07:00"))
        assertFalse(GuardPrefs.isInCurfew(LocalTime.of(12, 0), "21:30", "07:00"))
        assertTrue(GuardPrefs.isInCurfew(LocalTime.of(13, 0), "12:00", "14:00"))
        assertFalse(GuardPrefs.isInCurfew(LocalTime.of(15, 0), "12:00", "14:00"))
    }

    @Test
    fun normalizeHhmmSanitizesInput() {
        assertEquals("08:05", GuardPrefs.normalizeHhmm("8:5", "21:30"))
        assertEquals("21:30", GuardPrefs.normalizeHhmm("99:99", "21:30"))
    }
}
